<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import AppIcon from '../components/AppIcon.vue'
import MaterialPicker from '../components/MaterialPicker.vue'
import LayoutEditor from '../components/LayoutEditor.vue'
import { useCreator } from '../composables/useCreator'
import { fieldKeys, fieldLabels, styleLabels } from '../api/types'
import { useServiceStore } from '../stores/service'
const c = useCreator()
const service = useServiceStore()
const route = useRoute()
/** 在项目上下文里打开时，非空；用于"返回项目"和锁定作品类型。 */
const projectId = computed(() => (typeof route.params.projectId === 'string' ? route.params.projectId : ''))
const { task, draft, template, visibleTemplates, loading, busy, operation, error, requestId, conflict,
  saveError, dirty, recovered, recoveryText, checked, job, waitLong, step, currentPreview, canConfirm, saveLabel, progressLabel, sessionLost, crossSessionRecovery, restoringJob, styleFilter, recommendedIds, beforeFields, proposedFields, exportScale } = c
const zoomOpen = ref(false)
const materialOpen = ref(false)
const zoom = ref(100)
const previewFailed = ref(false)
const previewUrl = computed(() => currentPreview.value ? `/api/assets/${task.value!.previewAssetId}/file` : '')
watch(previewUrl, () => { previewFailed.value = false; zoomOpen.value = false })
const analysisValid = computed(() => !!task.value?.analysis && !dirty.value)
const imageUrl = computed(() => draft.assetIds[0] ? `/api/assets/${draft.assetIds[0]}/file` : '')
</script>
<template>
  <div class="page creator-page">
    <div class="creator-heading"><div><RouterLink :to="projectId ? '/projects/' + projectId : '/'" class="back-link"><AppIcon name="back" :size="16" />{{ projectId ? '返回项目' : '返回工作台' }}</RouterLink><h1>{{ task?.displayName || task?.fields.title || '开始一份新创作' }}</h1></div><div class="creator-heading-actions"><span :class="['save-state', { unsaved: dirty || saveError || conflict }]"><span :class="{ spinner: c.saving.value }" /><AppIcon v-if="!c.saving.value && !dirty && task" name="check" :size="15" />{{ saveLabel }}</span><button class="button outline compact" :disabled="busy || conflict || sessionLost || !draft.rawText.trim()" @click="c.save">保存草稿</button></div></div>
    <ol class="stepper" aria-label="创作步骤"><li v-for="(label, index) in ['输入与推荐', '补充与确认', '预览与下载']" :key="label" :class="{ current: step === index + 1, complete: step > index + 1 }"><button :disabled="busy || (index > 0 && !task?.analysis)" @click="step = index + 1"><span class="step-dot"><AppIcon v-if="step > index + 1" name="check" :size="14" /><template v-else>{{ index + 1 }}</template></span>{{ label }}</button></li></ol>
    <div v-if="error" class="error-card creator-error" role="alert"><AppIcon name="warning" /><div><strong>{{ error }}</strong><small v-if="requestId">请求编号：{{ requestId }}</small><button v-if="sessionLost" class="text-button" @click="c.reconnect">重新连接会话</button><button v-else-if="conflict" class="text-button" @click="c.reloadServer">重新载入服务器版本</button><button v-else-if="job || task?.phase === 'rendering'" class="text-button" @click="c.retryJob">继续查看任务</button><button v-else-if="saveError" class="text-button" @click="c.save">重试保存</button><button v-else-if="loading || !visibleTemplates.length" class="text-button" @click="c.initialize(task?.id)">重新连接</button><button class="text-button" @click="error = ''">关闭提示</button></div></div>
    <div v-if="recovered" class="recovery-card"><strong>{{ crossSessionRecovery ? '已建立新会话，请选择是否复制原文字' : conflict ? '已保留本地修改' : '发现上次未保存的内容' }}</strong><p>{{ crossSessionRecovery ? '原会话的作品和图片不会自动带入。选择复制文字后，才会建立新会话的草稿；如需原图片，请重新上传。' : '本地副本只属于当前会话。可以恢复到编辑区，也可以展开复制文本后，再决定使用哪个版本。' }}</p><details><summary>查看保留的内容</summary><textarea :value="recoveryText" readonly aria-label="本地保留的内容" /></details><div class="inline-actions"><button v-if="!conflict && !sessionLost" class="button outline compact" @click="c.restore">{{ crossSessionRecovery ? '复制文字到新会话' : '恢复到编辑区' }}</button><button class="text-button" @click="c.discardRecovery">忽略这份副本</button></div></div>
    <div v-if="loading" class="empty-state"><span class="spinner" /><p>正在准备创作空间…</p></div>
    <div v-else class="creator-grid">
      <section class="editor-panel">
        <fieldset :disabled="busy || conflict || sessionLost" class="editor-fieldset">
          <template v-if="step === 1">
            <div class="panel-heading"><div><span class="eyebrow">第一步</span><h2>先说说，你的想法。</h2></div><span class="number-tag">01</span></div>
            <template v-if="!projectId"><label class="field-label">作品类型</label><div class="scenario-options"><button :class="{ selected: draft.scenario === 'poster' }" @click="c.changeScenario('poster')"><AppIcon name="file" :size="16" /><span>竖版海报<small>1080 × 1440</small></span></button><button :class="{ selected: draft.scenario === 'article_image' }" @click="c.changeScenario('article_image')"><AppIcon name="image" :size="16" /><span>公众号配图<small>1200 × 675</small></span></button></div></template>
            <label class="field-label" for="raw-text">创作内容<span class="required">必填</span></label><p class="field-help">写下标题、正文、时间、地点等信息，也可以从示例开始。</p>
            <textarea id="raw-text" v-model="draft.rawText" class="raw-input" maxlength="10000" placeholder="例如：做一张校园读书会海报。标题：秋日读书会。时间：2026年11月7日14:00。地点：图书馆一楼交流区。正文：带上一本喜欢的书，分享你的阅读故事。" /><div class="input-foot"><span>已填 {{ Array.from(draft.rawText).length }} / 10000 字</span><span>{{ task ? '停止输入 0.8 秒后自动同步' : c.localStorageError.value ? '浏览器暂存不可用，请点击“保存草稿”' : '新稿暂存在此浏览器；保存后进入历史作品' }}</span></div>
            <div v-if="!task" class="sample-actions"><span>试试示例</span><button class="sample-chip" @click="c.sample(true)">完整活动文案<AppIcon name="arrow" :size="13" /></button><button class="sample-chip" @click="c.sample(false)">缺失信息文案<AppIcon name="arrow" :size="13" /></button></div>
            <div class="recommendation-action"><button class="button outline" :disabled="!draft.rawText.trim()" @click="c.analyze">分析需求并推荐模板<AppIcon name="spark" :size="17" /></button><p class="field-help">先分析文字，再参考推荐手动选择模板。也可直接选择下方模板。</p></div>
            <div class="section-divider" />
            <div v-if="recommendedIds.length" class="success-notice"><AppIcon name="check" :size="18" />已匹配推荐模板，请选择一款后处理内容。</div>
            <div class="label-row"><label class="field-label">选择模板<span class="required">必选</span></label><span class="field-help">{{ visibleTemplates.length }} 款可用</span></div><p class="field-help">模板决定版式，内容会按模板要求进行检查。</p>
            <label class="template-filter">风格筛选<select v-model="styleFilter"><option value="all">全部风格</option><option v-for="(label, value) in styleLabels" :key="value" :value="value">{{ label }}</option></select></label>
            <div class="template-list"><button v-for="item in visibleTemplates" :key="item.id" :class="['template-option', { selected: draft.templateId === item.id }]" @click="c.chooseTemplate(item)"><span class="template-mini"><img :src="item.thumbnailUrl" :alt="`${item.name}缩略图`" @error="($event.target as HTMLImageElement).style.visibility = 'hidden'" /><AppIcon name="file" :size="22" /></span><span class="template-option-copy"><strong>{{ item.name }}<span v-if="recommendedIds.includes(item.id)" class="recommend-badge">推荐</span></strong><small>{{ styleLabels[item.style] }} · {{ item.scenario === 'poster' ? '竖版海报' : '公众号配图' }}</small></span><span class="radio-dot"><AppIcon v-if="draft.templateId === item.id" name="check" :size="12" /></span></button></div>
            <div v-if="!visibleTemplates.length" class="inline-notice">当前筛选下没有模板，请切换风格；若全部为空，请重新连接服务。</div>
            <div class="section-divider" />
            <div class="label-row"><label class="field-label" for="image-upload">添加图片<span class="optional">可选</span></label><span class="field-help">JPG / PNG · 最大 10 MiB</span></div>
            <div v-if="imageUrl" class="upload-preview"><img :src="imageUrl" alt="已上传的原始图片" /><div><strong>图片已上传</strong><p>原图保留，生成时按模板等比适配。</p><button class="text-button" @click="c.removeImage">移除图片</button></div></div>
            <label v-else class="upload-zone" for="image-upload"><AppIcon name="upload" :size="25" /><strong>点击选择一张图片</strong><span>也可以不上传，使用纯文字版式。</span></label><input id="image-upload" type="file" class="file-input" accept="image/jpeg,image/png" @change="c.upload" />
            <p v-if="imageUrl" class="field-help"><label class="text-button" for="image-upload">替换图片</label></p><button type="button" class="button outline compact library-select" @click="materialOpen = true">从素材库选择</button>
            <div class="editor-bottom"><p><AppIcon name="spark" :size="15" />{{ service.health?.mode === 'real' ? '真实模型处理，结果请逐项确认' : 'Mock 确定性提取，不调用真实大模型' }}</p><button class="button primary" :disabled="!draft.rawText.trim() || !draft.templateId" @click="c.analyze">处理内容并检查信息<AppIcon name="arrow" :size="17" /></button></div>
          </template>
          <template v-else-if="step === 2">
            <div class="panel-heading"><div><span class="eyebrow">第二步</span><h2>每个细节，由你确认。</h2></div><span class="number-tag">02</span></div>
            <div v-if="task?.analysis?.missingFields.length && !dirty" class="missing-notice"><AppIcon name="warning" /><div><strong>还有 {{ task.analysis.missingFields.length }} 项信息需要补充</strong><p v-for="question in task.analysis.questions" :key="question.field">{{ question.question }}</p></div></div>
            <div v-else-if="dirty || !task?.analysis" class="inline-notice">内容已修改。保存后点击“重新分析并检查”，更新追问和事实清单。</div>
            <div v-else class="success-notice"><AppIcon name="check" :size="18" />必填信息已完整，请核对内容和重要事实。</div>
            <details class="source-comparison" open><summary>原文与处理结果对照</summary><p class="field-help">原文保持不变。下方每个字段可单独保留处理前文字或采用处理结果；修改后需重新分析并确认事实。</p><blockquote>{{ draft.rawText }}</blockquote></details>
            <div class="metadata-grid"><div v-for="key in fieldKeys" :key="key" :class="['metadata-field', { 'full-width': key === 'body' || key === 'title', missing: task?.analysis?.missingFields.includes(key) && !dirty }]"><label class="field-label" :for="`field-${key}`">{{ fieldLabels[key] }}<span v-if="c.fieldRequired(key)" class="required">*</span><span class="field-counter">{{ Array.from(draft.fields[key]).length }} / {{ template?.fields[key].maxChars || '—' }}</span></label><textarea v-if="key === 'body'" :id="`field-${key}`" v-model="draft.fields[key]" rows="5" :placeholder="template?.fields[key].question" /><input v-else :id="`field-${key}`" v-model="draft.fields[key]"  :placeholder="template?.fields[key].question" /><div v-if="beforeFields && proposedFields" class="field-comparison"><div><small>处理前字段</small><p>{{ beforeFields[key] || '（空）' }}</p><button class="text-button" @click="c.keepField(key, 'before')">保留处理前</button></div><div><small>处理结果</small><p>{{ proposedFields[key] || '（空）' }}</p><button class="text-button" @click="c.keepField(key, 'proposed')">采用处理结果</button></div></div></div></div>
            <div class="inline-actions metadata-actions"><button class="button outline compact" @click="c.analyze"><AppIcon name="refresh" :size="16" />重新分析并检查</button><span class="field-help">重要事实不会自动补写</span></div>
            <div v-if="analysisValid" class="facts-panel"><div class="label-row"><h3>重要事实清单</h3><span class="field-help">版本 {{ task?.revision }}</span></div><p class="field-help">请逐项核对。修改内容后，需要重新分析和确认。</p><label v-for="fact in task?.analysis?.facts" :key="fact.id" class="fact-item"><input v-model="checked" type="checkbox" :value="fact.id" /><span>{{ fact.value }}</span><span class="fact-check">确认无误</span></label><p v-if="!task?.analysis?.facts.length" class="field-help">未识别到额外的时间、地点等事实，请仍检查上方全部内容。</p><p v-for="warning in task?.analysis?.warnings" :key="warning" class="inline-notice">{{ warning }}</p></div>
            <div class="editor-bottom"><button class="text-button" @click="step = 1"><AppIcon name="back" :size="16" />返回输入</button><button class="button primary" :disabled="!canConfirm" @click="c.confirmAndRender"><AppIcon name="spark" :size="18" />确认并生成作品</button></div>
          </template>
          <template v-else>
            <div class="panel-heading"><div><span class="eyebrow">第三步</span><h2>{{ currentPreview ? '你的作品，准备好了。' : '让灵感，成为作品。' }}</h2></div><span class="number-tag">03</span></div><div class="completion-card"><span class="completion-icon"><AppIcon :name="currentPreview ? 'check' : 'image'" :size="30" /></span><h3>{{ currentPreview ? '这一份创作，可以分享了。' : '当前版本还没有生成预览' }}</h3><p>{{ currentPreview ? '预览与下载使用同一张服务端生成图片。' : '返回检查内容，确认重要事实后重新生成。' }}</p></div><dl class="export-info"><div><dt>作品模板</dt><dd>{{ template?.name || '尚未选择' }}</dd></div><div><dt>导出尺寸</dt><dd>{{ template ? `${template.canvas.width * exportScale} × ${template.canvas.height * exportScale} 像素` : '由模板决定' }}</dd></div><div><dt>当前版本</dt><dd>{{ task?.revision }}<span v-if="dirty"> · 有未保存修改</span></dd></div><div><dt>内容分析</dt><dd>{{ task?.analysisMode === 'real' ? '真实模型' : 'Mock 演示模式' }}</dd></div></dl><label class="export-scale">导出分辨率<select v-model="exportScale"><option :value="1">模板原始分辨率</option><option :value="2">2 倍像素放大</option></select></label><p class="field-help">{{ exportScale === 2 ? '2 倍是普通像素放大，不是无损增强；原图细节不会增加。' : '按模板原始像素导出，保留当前实际排版。' }}</p><div class="download-actions"><button class="button primary" :disabled="!currentPreview" @click="c.download('png')"><AppIcon name="download" />下载 PNG</button><button class="button outline" :disabled="!currentPreview" @click="c.download('jpg')">下载 JPG</button><button class="button outline" :disabled="!currentPreview" @click="c.download('pdf')">下载 PDF</button></div><button class="text-button edit-again" @click="step = 2"><AppIcon name="back" :size="16" />返回修改内容</button><p class="field-help">修改文字、图片或模板后，原确认与下载会失效，需要重新生成。</p>
          </template>
        </fieldset>
      </section>
      <aside class="preview-panel"><div class="preview-heading"><div><AppIcon name="image" :size="18" /><h2>作品预览</h2></div><span>{{ template ? `${template.canvas.width} × ${template.canvas.height}` : '原尺寸导出' }}</span></div><div :class="['preview-stage', { 'has-preview': currentPreview }]">
          <button v-if="previewUrl && !previewFailed" class="preview-image-button" title="放大查看作品" @click="zoomOpen = true; zoom = 100"><img class="generated-preview" :src="previewUrl" @error="previewFailed = true" :alt="`${task?.fields.title || '作品'}的服务端生成预览`" /></button>
          <div v-else-if="previewFailed" class="preview-placeholder"><h3>预览图片加载失败</h3><button class="button outline" @click="previewFailed = false">重试加载</button></div><div v-else-if="job || restoringJob" class="preview-progress" role="status"><span class="spinner big" /><h3>{{ progressLabel }}</h3><p>服务端排版任务正在处理，请稍候。</p><div class="progress-track"><span :style="{ width: `${job?.progress || 0}%` }" /></div><span>{{ job?.progress || 0 }}%</span><p v-if="job?.queuePosition" class="field-help">当前排队位置：第 {{ job.queuePosition }} 位</p><p v-if="waitLong" class="field-help">任务仍在处理，可以离开页面，稍后继续查看。</p></div>
          <div v-else class="preview-placeholder"><div class="placeholder-paper"><span /><span /><span /><AppIcon name="image" :size="44" /><span /><span /></div><h3>{{ dirty && task ? '内容已修改，等待重新生成' : '好作品，从一句话开始。' }}</h3><p>补齐内容并确认重要事实后，<br>这里将展示真实生成的图片。</p></div>
        </div><div class="preview-footer"><span><span class="status-dot" />{{ currentPreview ? '当前版本 · 可下载' : job ? '正在生成 · 草稿已保存' : '尚未生成图片' }}</span><span>服务端排版</span></div><div class="preview-tip"><AppIcon name="spark" :size="18" /><p><strong>一点创作小建议</strong><br>标题简洁一点，正文清楚一点。把时间和地点写完整，让信息和设计一起被看见。</p></div><LayoutEditor v-if="task?.templateId" :task="task" :busy="busy || conflict || sessionLost" :flush="c.prepareLayout" @saved="c.applyLayout" /></aside>
    </div>
    <MaterialPicker v-if="materialOpen" @close="materialOpen = false" @selected="id => { draft.assetIds = [id]; materialOpen = false }" />
    <div v-if="zoomOpen" class="preview-modal" role="dialog" aria-modal="true" aria-label="放大查看作品" @click.self="zoomOpen = false"><div class="preview-modal-toolbar"><strong>作品细节</strong><label>缩放<select v-model="zoom"><option :value="50">50%</option><option :value="100">100%</option><option :value="150">150%</option><option :value="200">200%</option></select></label><button class="button outline compact" @click="zoomOpen = false">关闭预览</button></div><div class="preview-modal-scroll"><img :src="previewUrl" :alt="task?.fields.title || '作品'" :style="{ width: template ? template.canvas.width * zoom / 100 + 'px' : zoom + '%', maxWidth: 'none' }" /></div></div>
    <div v-if="busy && !loading && !job && !restoringJob" class="operation-toast" role="status"><span class="spinner" />{{ operation }}</div>
  </div>
</template>
